using AlSsareea.BuildingBlocks.Domain;

namespace AlSsareea.Modules.Catalog.Domain;

public sealed class Product : AggregateRoot<ProductId>
{
    private readonly List<ProductTranslation> _translations = []; private readonly List<ProductVariant> _variants = []; private readonly List<OptionGroup> _optionGroups = []; private readonly List<ProductImageReference> _images = []; private readonly List<ProductAvailabilitySchedule> _availability = [];
    private Product(ProductId id) : base(id) { Currency = null!; }
    private Product(ProductId id, CatalogId catalogId, Guid merchantId, CategoryId? categoryId, string? sku, long price, string currency, string? tax, int sort, DateTime now) : base(id) { if (price < 0) throw new DomainException("Base price cannot be negative."); CatalogId = catalogId; MerchantId = CatalogRules.Id(merchantId, nameof(merchantId)); CategoryId = categoryId; Sku = CatalogRules.Optional(sku, 100, nameof(sku)); BasePriceMinor = price; Currency = CatalogRules.Currency(currency); TaxCategoryReference = CatalogRules.Optional(tax, 100, nameof(tax)); CatalogRules.Sort(sort); SortOrder = sort; Status = ProductStatus.Draft; InventoryStatus = InventoryStatus.InStock; IsVisible = true; CurrentVersion = 1; CreatedAtUtc = UpdatedAtUtc = now; ConcurrencyStamp = Guid.NewGuid(); }
    public CatalogId CatalogId { get; private set; }
    public Guid MerchantId { get; private set; }
    public CategoryId? CategoryId { get; private set; }
    public string? Sku { get; private set; }
    public long BasePriceMinor { get; private set; }
    public string Currency { get; private set; } = null!; public string? TaxCategoryReference { get; private set; }
    public ProductStatus Status { get; private set; }
    public InventoryStatus InventoryStatus { get; private set; }
    public int SortOrder { get; private set; }
    public bool IsVisible { get; private set; }
    public bool IsFeatured { get; private set; }
    public int CurrentVersion { get; private set; }
    public DateTime CreatedAtUtc { get; private set; }
    public DateTime UpdatedAtUtc { get; private set; }
    public DateTime? PublishedAtUtc { get; private set; }
    public Guid ConcurrencyStamp { get; private set; }
    public IReadOnlyCollection<ProductTranslation> Translations => _translations; public IReadOnlyCollection<ProductVariant> Variants => _variants; public IReadOnlyCollection<OptionGroup> OptionGroups => _optionGroups; public IReadOnlyCollection<ProductImageReference> Images => _images; public IReadOnlyCollection<ProductAvailabilitySchedule> Availability => _availability;
    public static Product Create(ProductId id, CatalogId catalogId, Guid merchantId, CategoryId? categoryId, string? sku, long price, string currency, string? tax, int sort, DateTime now) { CatalogRules.Utc(now); return new(id, catalogId, merchantId, categoryId, sku, price, currency, tax, sort, now); }
    public void SetTranslation(string language, string name, string? description, DateTime now) { string lang = CatalogRules.Language(language); ProductTranslation? x = _translations.SingleOrDefault(v => v.LanguageCode == lang); if (x is null) _translations.Add(new ProductTranslation(Id, lang, name, description)); else x.Update(name, description); Changed(now); }
    public void UpdateCommercial(long price, string currency, string? tax, CategoryId? categoryId, int sort, DateTime now) { if (price < 0) throw new DomainException("Base price cannot be negative."); BasePriceMinor = price; Currency = CatalogRules.Currency(currency); TaxCategoryReference = CatalogRules.Optional(tax, 100, nameof(tax)); CategoryId = categoryId; CatalogRules.Sort(sort); SortOrder = sort; Changed(now); }
    public void Publish(string defaultLanguage, DateTime now) { if (Status is not (ProductStatus.Draft or ProductStatus.Suspended) || !_translations.Any(x => x.LanguageCode == CatalogRules.Language(defaultLanguage))) throw new DomainException("Product requires its default-language translation before publishing."); Status = ProductStatus.Active; PublishedAtUtc ??= now; Changed(now); }
    public void Suspend(DateTime now) { if (Status != ProductStatus.Active) throw new DomainException("Only active products can be suspended."); Status = ProductStatus.Suspended; Changed(now); }
    public void Archive(DateTime now) { Status = ProductStatus.Archived; IsVisible = false; Changed(now); }
    public void SetVisibility(bool visible, DateTime now) { if (Status == ProductStatus.Archived && visible) throw new DomainException("Archived product cannot be shown."); IsVisible = visible; Changed(now); }
    public void SetInventory(InventoryStatus status, DateTime now) { InventoryStatus = status; Changed(now); }
    public ProductVariant AddVariant(string language, string name, string? sku, long adjustment, InventoryStatus inventory, bool isDefault, int sort, DateTime now) { if (BasePriceMinor + adjustment < 0) throw new DomainException("Variant final price cannot be negative."); if (isDefault && inventory is InventoryStatus.OutOfStock or InventoryStatus.Unavailable) throw new DomainException("Unavailable variant cannot be default."); if (isDefault) foreach (ProductVariant v in _variants) v.ClearDefault(); ProductVariant value = new(ProductVariantId.New(), Id, MerchantId, sku, adjustment, inventory, isDefault, sort, language, name, now); _variants.Add(value); Changed(now); return value; }
    public OptionGroup AddOptionGroup(string language, string name, SelectionType type, bool required, int min, int max, int sort, DateTime now) { OptionGroup value = new(OptionGroupId.New(), Id, MerchantId, type, required, min, max, sort, language, name, now); _optionGroups.Add(value); Changed(now); return value; }
    public ProductImageReference AddImage(Guid? mediaId, string? external, string? alt, int sort, bool primary, DateTime now) { if (primary) foreach (ProductImageReference image in _images) image.ClearPrimary(); ProductImageReference value = new(ProductImageReferenceId.New(), Id, MerchantId, mediaId, external, alt, sort, primary, now); _images.Add(value); Changed(now); return value; }
    public ProductAvailabilitySchedule AddAvailability(Guid? branchId, DayOfWeek day, TimeOnly start, TimeOnly end, string timeZone, DateTime now) { ProductAvailabilitySchedule value = new(ProductAvailabilityScheduleId.New(), Id, MerchantId, branchId, day, start, end, timeZone); _availability.Add(value); Changed(now); return value; }
    public void ReplaceAvailability(IEnumerable<(Guid? BranchId, DayOfWeek Day, TimeOnly Start, TimeOnly End, string TimeZone)> periods, DateTime now)
    {
        _availability.Clear();
        foreach ((Guid? branchId, DayOfWeek day, TimeOnly start, TimeOnly end, string timeZone) in periods)
            _availability.Add(new ProductAvailabilitySchedule(ProductAvailabilityScheduleId.New(), Id, MerchantId, branchId, day, start, end, timeZone));
        Changed(now);
    }
    public void MarkOptionsChanged(DateTime now) => Changed(now);
    public ProductVariant UpdateVariant(ProductVariantId id, string language, string name, string? sku, long adjustment, InventoryStatus inventory, bool visible, int sort, DateTime now)
    {
        if (BasePriceMinor + adjustment < 0) throw new DomainException("Variant final price cannot be negative.");
        ProductVariant variant = _variants.SingleOrDefault(x => x.Id == id) ?? throw new DomainException("Variant does not belong to product.");
        variant.Update(language, name, sku, adjustment, inventory, visible, sort, now);
        if ((!visible || inventory is InventoryStatus.OutOfStock or InventoryStatus.Unavailable) && variant.IsDefault) variant.ClearDefault();
        Changed(now); return variant;
    }
    public void SetDefaultVariant(ProductVariantId id, DateTime now)
    {
        ProductVariant value = _variants.SingleOrDefault(x => x.Id == id) ?? throw new DomainException("Variant does not belong to product.");
        if (!value.IsVisible || value.InventoryStatus is InventoryStatus.OutOfStock or InventoryStatus.Unavailable) throw new DomainException("Unavailable variant cannot be default.");
        foreach (ProductVariant variant in _variants) variant.ClearDefault();
        value.MakeDefault(); Changed(now);
    }
    public void ReorderVariants(IReadOnlyDictionary<ProductVariantId, int> orders, DateTime now)
    {
        if (orders.Count != _variants.Count || _variants.Any(x => !orders.ContainsKey(x.Id))) throw new DomainException("All variants must be included exactly once.");
        foreach (ProductVariant variant in _variants) variant.Reorder(orders[variant.Id], now);
        Changed(now);
    }
    public OptionGroup UpdateOptionGroup(OptionGroupId id, string language, string name, SelectionType type, bool required, int min, int max, int sort, DateTime now)
    {
        OptionGroup group = _optionGroups.SingleOrDefault(x => x.Id == id) ?? throw new DomainException("Option group does not belong to product.");
        group.Update(language, name, type, required, min, max, sort, now); Changed(now); return group;
    }
    public void ReorderOptionGroups(IReadOnlyDictionary<OptionGroupId, int> orders, DateTime now)
    {
        if (orders.Count != _optionGroups.Count || _optionGroups.Any(x => !orders.ContainsKey(x.Id))) throw new DomainException("All option groups must be included exactly once.");
        foreach (OptionGroup group in _optionGroups) group.Reorder(orders[group.Id], now);
        Changed(now);
    }
    public ProductOption UpdateOption(OptionGroupId groupId, ProductOptionId optionId, string language, string name, long adjustment, bool isDefault, bool available, int sort, DateTime now)
    {
        OptionGroup group = _optionGroups.SingleOrDefault(x => x.Id == groupId) ?? throw new DomainException("Option group does not belong to product.");
        ProductOption option = group.UpdateOption(optionId, language, name, adjustment, isDefault, available, sort, now); Changed(now); return option;
    }
    public void ReorderOptions(OptionGroupId groupId, IReadOnlyDictionary<ProductOptionId, int> orders, DateTime now)
    {
        OptionGroup group = _optionGroups.SingleOrDefault(x => x.Id == groupId) ?? throw new DomainException("Option group does not belong to product.");
        group.ReorderOptions(orders, now); Changed(now);
    }
    public ProductImageReference UpdateImage(ProductImageReferenceId id, Guid? mediaId, string? external, string? alt, int sort, bool primary, DateTime now)
    {
        ProductImageReference image = _images.SingleOrDefault(x => x.Id == id) ?? throw new DomainException("Image does not belong to product.");
        if (primary) foreach (ProductImageReference value in _images) value.ClearPrimary();
        image.Update(mediaId, external, alt, sort, primary); Changed(now); return image;
    }
    public void SetPrimaryImage(ProductImageReferenceId id, DateTime now)
    {
        ProductImageReference image = _images.SingleOrDefault(x => x.Id == id) ?? throw new DomainException("Image does not belong to product.");
        foreach (ProductImageReference value in _images) value.ClearPrimary();
        image.MakePrimary(); Changed(now);
    }
    public void RemoveImage(ProductImageReferenceId id, DateTime now)
    {
        if (_images.RemoveAll(x => x.Id == id) == 0) throw new DomainException("Image does not belong to product.");
        Changed(now);
    }
    public void ReorderImages(IReadOnlyDictionary<ProductImageReferenceId, int> orders, DateTime now)
    {
        if (orders.Count != _images.Count || _images.Any(x => !orders.ContainsKey(x.Id))) throw new DomainException("All images must be included exactly once.");
        foreach (ProductImageReference image in _images) image.Reorder(orders[image.Id]);
        Changed(now);
    }
    public bool IsPurchasable => Status == ProductStatus.Active && IsVisible && InventoryStatus is InventoryStatus.InStock or InventoryStatus.LowStock;
    public bool IsAvailableAt(DateTime atUtc, Guid? branchId) { if (!IsPurchasable) return false; ProductAvailabilitySchedule[] schedules = _availability.Where(x => x.IsEnabled && x.MerchantBranchId == branchId).ToArray(); return schedules.Length == 0 || schedules.Any(x => x.Contains(atUtc)); }
    private void Changed(DateTime now) { CatalogRules.Utc(now); UpdatedAtUtc = now; CurrentVersion++; ConcurrencyStamp = Guid.NewGuid(); RaiseDomainEvent(new ProductChangedDomainEvent(Id, CurrentVersion, now)); }
}

public sealed class ProductTranslation { private ProductTranslation() { LanguageCode = Name = SearchText = null!; } internal ProductTranslation(ProductId id, string language, string name, string? description) { ProductId = id; LanguageCode = CatalogRules.Language(language); Update(name, description); } public ProductId ProductId { get; private set; } public string LanguageCode { get; private set; } public string Name { get; private set; } = null!; public string? Description { get; private set; } public string SearchText { get; private set; } = null!; internal void Update(string name, string? description) { Name = CatalogRules.Required(name, 200, nameof(name)); Description = CatalogRules.Optional(description, 4000, nameof(description)); SearchText = (Name + " " + Description).Trim().ToLowerInvariant(); } }
public sealed class ProductVariant : Entity<ProductVariantId> { private readonly List<ProductVariantTranslation> _translations = []; private ProductVariant(ProductVariantId id) : base(id) { } internal ProductVariant(ProductVariantId id, ProductId productId, Guid merchantId, string? sku, long adjustment, InventoryStatus inventory, bool isDefault, int sort, string language, string name, DateTime now) : base(id) { ProductId = productId; MerchantId = merchantId; Sku = CatalogRules.Optional(sku, 100, nameof(sku)); PriceAdjustmentMinor = adjustment; InventoryStatus = inventory; IsDefault = isDefault; IsVisible = true; CatalogRules.Sort(sort); SortOrder = sort; CreatedAtUtc = UpdatedAtUtc = now; ConcurrencyStamp = Guid.NewGuid(); _translations.Add(new ProductVariantTranslation(id, language, name)); } public ProductId ProductId { get; private set; } public Guid MerchantId { get; private set; } public string? Sku { get; private set; } public long PriceAdjustmentMinor { get; private set; } public InventoryStatus InventoryStatus { get; private set; } public bool IsDefault { get; private set; } public bool IsVisible { get; private set; } public int SortOrder { get; private set; } public DateTime CreatedAtUtc { get; private set; } public DateTime UpdatedAtUtc { get; private set; } public Guid ConcurrencyStamp { get; private set; } public IReadOnlyCollection<ProductVariantTranslation> Translations => _translations; internal void ClearDefault() => IsDefault = false; internal void MakeDefault() => IsDefault = true; internal void Update(string language, string name, string? sku, long adjustment, InventoryStatus inventory, bool visible, int sort, DateTime now) { Sku = CatalogRules.Optional(sku, 100, nameof(sku)); PriceAdjustmentMinor = adjustment; InventoryStatus = inventory; IsVisible = visible; Reorder(sort, now); ProductVariantTranslation? translation = _translations.SingleOrDefault(x => x.LanguageCode == CatalogRules.Language(language)); if (translation is null) _translations.Add(new ProductVariantTranslation(Id, language, name)); else translation.Update(name); } internal void Reorder(int sort, DateTime now) { CatalogRules.Sort(sort); SortOrder = sort; UpdatedAtUtc = now; ConcurrencyStamp = Guid.NewGuid(); } }
public sealed class ProductVariantTranslation { private ProductVariantTranslation() { LanguageCode = Name = null!; } internal ProductVariantTranslation(ProductVariantId id, string language, string name) { ProductVariantId = id; LanguageCode = CatalogRules.Language(language); Update(name); } public ProductVariantId ProductVariantId { get; private set; } public string LanguageCode { get; private set; } public string Name { get; private set; } = null!; internal void Update(string name) => Name = CatalogRules.Required(name, 200, nameof(name)); }
public sealed class OptionGroup : Entity<OptionGroupId> { private readonly List<OptionGroupTranslation> _translations = []; private readonly List<ProductOption> _options = []; private OptionGroup(OptionGroupId id) : base(id) { } internal OptionGroup(OptionGroupId id, ProductId productId, Guid merchantId, SelectionType type, bool required, int min, int max, int sort, string language, string name, DateTime now) : base(id) { Validate(type, required, min, max); ProductId = productId; MerchantId = merchantId; SelectionType = type; IsRequired = required; MinSelections = min; MaxSelections = max; CatalogRules.Sort(sort); SortOrder = sort; IsVisible = true; CreatedAtUtc = UpdatedAtUtc = now; ConcurrencyStamp = Guid.NewGuid(); _translations.Add(new OptionGroupTranslation(id, language, name)); } public ProductId ProductId { get; private set; } public Guid MerchantId { get; private set; } public SelectionType SelectionType { get; private set; } public bool IsRequired { get; private set; } public int MinSelections { get; private set; } public int MaxSelections { get; private set; } public int SortOrder { get; private set; } public bool IsVisible { get; private set; } public DateTime CreatedAtUtc { get; private set; } public DateTime UpdatedAtUtc { get; private set; } public Guid ConcurrencyStamp { get; private set; } public IReadOnlyCollection<OptionGroupTranslation> Translations => _translations; public IReadOnlyCollection<ProductOption> Options => _options; public ProductOption AddOption(string language, string name, long adjustment, bool isDefault, bool available, int sort, DateTime now) { if (isDefault && !available) throw new DomainException("Default option must be available."); if (isDefault && _options.Count(x => x.IsDefault) >= MaxSelections) throw new DomainException("Default options exceed maximum selections."); ProductOption x = new(ProductOptionId.New(), Id, ProductId, MerchantId, adjustment, isDefault, available, sort, language, name, now); _options.Add(x); return x; } internal void Update(string language, string name, SelectionType type, bool required, int min, int max, int sort, DateTime now) { Validate(type, required, min, max); if (_options.Count(x => x.IsDefault) > max) throw new DomainException("Default options exceed maximum selections."); SelectionType = type; IsRequired = required; MinSelections = min; MaxSelections = max; Reorder(sort, now); OptionGroupTranslation? translation = _translations.SingleOrDefault(x => x.LanguageCode == CatalogRules.Language(language)); if (translation is null) _translations.Add(new OptionGroupTranslation(Id, language, name)); else translation.Update(name); } internal void Reorder(int sort, DateTime now) { CatalogRules.Sort(sort); SortOrder = sort; UpdatedAtUtc = now; ConcurrencyStamp = Guid.NewGuid(); } internal ProductOption UpdateOption(ProductOptionId id, string language, string name, long adjustment, bool isDefault, bool available, int sort, DateTime now) { ProductOption option = _options.SingleOrDefault(x => x.Id == id) ?? throw new DomainException("Option does not belong to group."); if (isDefault && !available) throw new DomainException("Default option must be available."); if (isDefault && !option.IsDefault && _options.Count(x => x.IsDefault) >= MaxSelections) throw new DomainException("Default options exceed maximum selections."); option.Update(language, name, adjustment, isDefault, available, sort, now); return option; } internal void ReorderOptions(IReadOnlyDictionary<ProductOptionId, int> orders, DateTime now) { if (orders.Count != _options.Count || _options.Any(x => !orders.ContainsKey(x.Id))) throw new DomainException("All options must be included exactly once."); foreach (ProductOption option in _options) option.Reorder(orders[option.Id], now); } private static void Validate(SelectionType type, bool required, int min, int max) { if (min < 0 || max < 1 || min > max || type == SelectionType.SingleChoice && max != 1 || required && min < 1) throw new DomainException("Option group selection limits are invalid."); } }
public sealed class OptionGroupTranslation { private OptionGroupTranslation() { LanguageCode = Name = null!; } internal OptionGroupTranslation(OptionGroupId id, string language, string name) { OptionGroupId = id; LanguageCode = CatalogRules.Language(language); Update(name); } public OptionGroupId OptionGroupId { get; private set; } public string LanguageCode { get; private set; } public string Name { get; private set; } = null!; internal void Update(string name) => Name = CatalogRules.Required(name, 200, nameof(name)); }
public sealed class ProductOption : Entity<ProductOptionId> { private readonly List<ProductOptionTranslation> _translations = []; private ProductOption(ProductOptionId id) : base(id) { } internal ProductOption(ProductOptionId id, OptionGroupId groupId, ProductId productId, Guid merchantId, long adjustment, bool isDefault, bool available, int sort, string language, string name, DateTime now) : base(id) { OptionGroupId = groupId; ProductId = productId; MerchantId = merchantId; PriceAdjustmentMinor = adjustment; IsDefault = isDefault; IsAvailable = available; CatalogRules.Sort(sort); SortOrder = sort; CreatedAtUtc = UpdatedAtUtc = now; ConcurrencyStamp = Guid.NewGuid(); _translations.Add(new ProductOptionTranslation(id, language, name)); } public OptionGroupId OptionGroupId { get; private set; } public ProductId ProductId { get; private set; } public Guid MerchantId { get; private set; } public long PriceAdjustmentMinor { get; private set; } public bool IsDefault { get; private set; } public bool IsAvailable { get; private set; } public int SortOrder { get; private set; } public DateTime CreatedAtUtc { get; private set; } public DateTime UpdatedAtUtc { get; private set; } public Guid ConcurrencyStamp { get; private set; } public IReadOnlyCollection<ProductOptionTranslation> Translations => _translations; internal void Update(string language, string name, long adjustment, bool isDefault, bool available, int sort, DateTime now) { PriceAdjustmentMinor = adjustment; IsDefault = isDefault; IsAvailable = available; Reorder(sort, now); ProductOptionTranslation? translation = _translations.SingleOrDefault(x => x.LanguageCode == CatalogRules.Language(language)); if (translation is null) _translations.Add(new ProductOptionTranslation(Id, language, name)); else translation.Update(name); } internal void Reorder(int sort, DateTime now) { CatalogRules.Sort(sort); SortOrder = sort; UpdatedAtUtc = now; ConcurrencyStamp = Guid.NewGuid(); } }
public sealed class ProductOptionTranslation { private ProductOptionTranslation() { LanguageCode = Name = null!; } internal ProductOptionTranslation(ProductOptionId id, string language, string name) { ProductOptionId = id; LanguageCode = CatalogRules.Language(language); Update(name); } public ProductOptionId ProductOptionId { get; private set; } public string LanguageCode { get; private set; } public string Name { get; private set; } = null!; internal void Update(string name) => Name = CatalogRules.Required(name, 200, nameof(name)); }
public sealed class ProductImageReference : Entity<ProductImageReferenceId> { private ProductImageReference(ProductImageReferenceId id) : base(id) { } internal ProductImageReference(ProductImageReferenceId id, ProductId productId, Guid merchantId, Guid? mediaId, string? external, string? alt, int sort, bool primary, DateTime now) : base(id) { ProductId = productId; MerchantId = merchantId; Update(mediaId, external, alt, sort, primary); CreatedAtUtc = now; } public ProductId ProductId { get; private set; } public Guid MerchantId { get; private set; } public Guid? MediaId { get; private set; } public string? ExternalReference { get; private set; } public string? AltText { get; private set; } public int SortOrder { get; private set; } public bool IsPrimary { get; private set; } public DateTime CreatedAtUtc { get; private set; } internal void ClearPrimary() => IsPrimary = false; internal void MakePrimary() => IsPrimary = true; internal void Update(Guid? mediaId, string? external, string? alt, int sort, bool primary) { if (mediaId is null && string.IsNullOrWhiteSpace(external)) throw new DomainException("A media ID or external reference is required."); MediaId = mediaId; ExternalReference = CatalogRules.Optional(external, 2000, nameof(external)); AltText = CatalogRules.Optional(alt, 500, nameof(alt)); Reorder(sort); IsPrimary = primary; } internal void Reorder(int sort) { CatalogRules.Sort(sort); SortOrder = sort; } }
public sealed class ProductAvailabilitySchedule : Entity<ProductAvailabilityScheduleId> { private ProductAvailabilitySchedule(ProductAvailabilityScheduleId id) : base(id) { TimeZoneId = null!; } internal ProductAvailabilitySchedule(ProductAvailabilityScheduleId id, ProductId productId, Guid merchantId, Guid? branchId, DayOfWeek day, TimeOnly start, TimeOnly end, string timeZone) : base(id) { ProductId = productId; MerchantId = merchantId; MerchantBranchId = branchId; DayOfWeek = day; StartLocalTime = start; EndLocalTime = end; try { _ = TimeZoneInfo.FindSystemTimeZoneById(timeZone); } catch (Exception e) when (e is TimeZoneNotFoundException or InvalidTimeZoneException) { throw new DomainException("Time zone is invalid."); } TimeZoneId = timeZone; IsEnabled = true; } public ProductId ProductId { get; private set; } public Guid MerchantId { get; private set; } public Guid? MerchantBranchId { get; private set; } public DayOfWeek DayOfWeek { get; private set; } public TimeOnly StartLocalTime { get; private set; } public TimeOnly EndLocalTime { get; private set; } public string TimeZoneId { get; private set; } public bool IsEnabled { get; private set; } public bool Contains(DateTime utc) { TimeZoneInfo zone = TimeZoneInfo.FindSystemTimeZoneById(TimeZoneId); DateTime local = TimeZoneInfo.ConvertTimeFromUtc(utc, zone); TimeOnly time = TimeOnly.FromDateTime(local); bool overnight = EndLocalTime <= StartLocalTime; DayOfWeek effective = overnight && time < EndLocalTime ? local.AddDays(-1).DayOfWeek : local.DayOfWeek; return effective == DayOfWeek && (overnight ? time >= StartLocalTime || time < EndLocalTime : time >= StartLocalTime && time < EndLocalTime); } }
